const VOICE_DATA = {"file":"voice/ep08.mp3","lines":{"ep08_001":{"who":"TAKUTO","text":"Previously. Plume Ogres raided a village. They were not hunting. They were running.","mono":true,"off":0.25,"dur":4.672,"env":"011776425698554245443100111898875436996224554422256666535344224653332103320004545556788512257641423100000000000154454368874321000000000000000"},"ep08_002":{"who":"TAKUTO","text":"Their chieftain could talk. He told us about the grey pack, and a wolf who walks like a man.","mono":true,"off":5.322,"dur":5.461,"env":"00576104553454110254421341023158763000000000000000001522389873486434525653013211355555410223555432000113444322378753111002332345531132232113334433321000000000000000"},"ep08_003":{"who":"TAKUTO","text":"His name is Kurozane. And he remembers Grey Hollow.","mono":true,"off":11.1833,"dur":3.52,"env":"0054425777776632235401115766653334432110000000000025565537656776534553420125666554322799842222100000000000"},"ep08_004":{"who":"TAKUTO","text":"That is where Sieg lost his whole squad.","mono":true,"off":15.1033,"dur":2.197,"env":"003798943488433236652235667753102422125543232015876421110000000000"},"ep08_005":{"who":"CROWD","text":"Sieg! Tell the one about the bear and the bishop again!","mono":false,"off":17.7007,"dur":3.051,"env":"01354677764200001327997375566554764003310476653321100014554205643323102310221111000000000000"},"ep08_006":{"who":"CROWD2","text":"Not again. He tells it wrong every time.","mono":false,"off":21.1513,"dur":2.24,"env":"02499987625777654321034132677533422467753213651244222234333221100000"},"ep08_007":{"who":"SIEG","text":"I tell it right. The bear is the one who changes.","mono":false,"off":23.7913,"dur":3.051,"env":"07872237976751047886667641200000000049867876665314764287667666778963342877787644543233321000"},"ep08_008":{"who":"SABLE","text":"Excuse me. Which way is the wind blowing tonight?","mono":false,"off":27.242,"dur":3.627,"env":"0017921787224455753332211000244234235866543454122322456433311134544333422124343333100110010000000000001000000"},"ep08_009":{"who":"CROWD","text":"Who are you? How did you get past the...","mono":false,"off":31.2687,"dur":2.347,"env":"00067778997754454432210136534323421541001214554245200122111000000000000"},"ep08_010":{"who":"SIEG","text":"The ropes! Somebody cut the alarm ropes!","mono":false,"off":34.0153,"dur":2.667,"env":"06999976676311332100000133987766656752027841006877666666666666777764321013321000"},"ep08_011":{"who":"SIEG","text":"MARA! JOSS! Everyone, UP!","mono":false,"off":37.082,"dur":2.261,"env":"07976666665555444347965556653333200000068768877776664204753200000000"},"ep08_012":{"who":"VENDOR","text":"Hunters, going up? Turn back, if you are wise. The wolf is on the mountain again.","mono":false,"off":39.7433,"dur":4.075,"env":"013987332755330476655555410001368767526533112211554433555543322212100000005656976420014334245544556455222333214543211100000"},"ep08_013":{"who":"VENDOR","text":"A wolf who walks like a man and wears a blade like a lord. He stops Hunters on the road and asks for a duel.","mono":false,"off":44.218,"dur":5.717,"env":"0365599763111175458630231642155676555433200255567665335421177666541344321345577665321110000000000045431296530122267622653354444436766544311143355533102100653226864311100000"},"ep08_014":{"who":"VENDOR","text":"Forty Hunters said yes. Forty Hunters are buried at the shrine.","mono":false,"off":50.3353,"dur":3.627,"env":"0149985654335776223643212564212576543221110000000159976654357652255433543212766566423101333326765432211100000"},"ep08_015":{"who":"WICK","text":"Forty. Why is it always forty?","mono":false,"off":54.362,"dur":1.749,"env":"00389986865449976764666776456645410566553221110000000"},"ep08_016":{"who":"NEMU","text":"Forty is a number that likes to be scary.","mono":false,"off":56.5113,"dur":3.072,"env":"000177998545532000000000764589878876433110000000000001351038875022315303543423235432111000000"},"ep08_017":{"who":"VENDOR","text":"He never kills the ones who refuse. That is the strange part. Only the ones who draw.","mono":false,"off":59.9833,"dur":4.693,"env":"007778754642022676654310554565543216645431016777542222100000047632654114432169666643101386653211100000079988766435446554331453236865422100000"},"ep08_018":{"who":"RIN","text":"He has rules.","mono":false,"off":65.0767,"dur":1.003,"env":"0266569532358876533311111000000"},"ep08_019":{"who":"SIEG","text":"He has a sense of theatre. It is not the same thing.","mono":false,"off":66.4793,"dur":3.179,"env":"089997546543226755322564200066666544444300000000058787656875553002653226666655541027654322210000"},"ep08_020":{"who":"TAKUTO","text":"Would you refuse?","mono":false,"off":70.058,"dur":1.131,"env":"0365246756981111456642111121000000"},"ep08_021":{"who":"SIEG","text":"...Ask me when he asks.","mono":false,"off":71.5887,"dur":1.301,"env":"0576652059766667887666654422002222100000"},"ep08_022":{"who":"WICK","text":"A hot spring. An actual hot spring. Takuto, this is the most Japanese thing that has ever happened to me here.","mono":false,"off":73.29,"dur":6.208,"env":"0453239984024410387665542266457630232775336776202430046543211100000000000189611398334876665422774426541287766531012777620566666533204554444345453322562564335640145213332211322110000000000"},"ep08_023":{"who":"TAKUTO","text":"You live in a world with a cat girl and a robot cube.","mono":false,"off":79.898,"dur":3.221,"env":"0024435994375654356566541123113002134554000123332210000002555323655652454320011123210000000000000"},"ep08_024":{"who":"WICK","text":"And THIS is the most Japanese thing! That should tell you how weird this world is!","mono":false,"off":83.5193,"dur":4.053,"env":"03798798443146422877876310138997206666766332045422121000000079413374132798665654378764336676533534202556541332211221000000"},"ep08_025":{"who":"NEMU","text":"Water that is already warm. I am going to live in it.","mono":false,"off":87.9727,"dur":3.904,"env":"0027898324210001343246520388755753542005665431100000000000000000000000000257985687783499987751723226861124211100031000"},"ep08_026":{"who":"RIN","text":"Your arm is healed. My ribs are healed. We have earned one night.","mono":false,"off":92.2767,"dur":3.392,"env":"038971688878974531055766552110466664379612455211455543321100000365751346666532135555444322100120000000"},"ep08_027":{"who":"SIEG","text":"One night. The pass shrine is a day up the road. Then two more to the capital.","mono":false,"off":96.0687,"dur":4.544,"env":"07976666655556412100000047316975554434327765556665225566535876664104666766654443200000000000698873342976777566654215552159641043332210000"},"ep08_028":{"who":"RIN","text":"You keep looking up the road.","mono":false,"off":101.0127,"dur":1.472,"env":"057313299620169811577740164598765443221000000"},"ep08_029":{"who":"SIEG","text":"Old habit.","mono":false,"off":102.8847,"dur":0.981,"env":"099987879969977778654233210000"},"ep08_030":{"who":"RIN","text":"Sieg. You have not laughed since the village.","mono":false,"off":104.266,"dur":2.091,"env":"023599997302579999359999425878753102356533074278655331022100000"},"ep08_031":{"who":"SIEG","text":"...Haven't I?","mono":false,"off":106.7567,"dur":1.067,"env":"01459876587757876676666553100000"},"ep08_032":{"who":"WICK","text":"Ahhh. Okay. I take it back. This is better than Osaka.","mono":false,"off":108.2233,"dur":2.901,"env":"0467744896113976635661368307310665431000015854355532287566455555543326542013332110000000"},"ep08_033":{"who":"NEMU","text":"Wick. Your head is boiling the water.","mono":false,"off":111.5247,"dur":2.304,"env":"0059510011000000068622258874120025440035576664555442442333333210100000"},"ep08_034":{"who":"WICK","text":"Is it? Oh. Oh no. Everyone is getting out. Sorry! Sorry!","mono":false,"off":114.2287,"dur":2.901,"env":"0454597100577766667666651014742576566642155454444321002232666554432324555322211000000000"},"ep08_035":{"who":"NEMU","text":"I am staying. It is perfect now.","mono":false,"off":117.53,"dur":2.496,"env":"014787764533236777543221000000000000000199485430321774113200004433211110000"},"ep08_036":{"who":"TAKUTO","text":"Nemu is going to fall asleep in there.","mono":false,"off":120.426,"dur":2.283,"env":"025678876788763344226544411159985444443124431014433333321110000000000"},"ep08_037":{"who":"RIN","text":"Then she will be the cleanest cat on the mountain.","mono":false,"off":123.1087,"dur":2.347,"env":"08988845446587268253021277667341011466520014556555655554221232110000000"},"ep08_038":{"who":"NEMU","text":"You like him.","mono":false,"off":125.8553,"dur":0.896,"env":"001697366665003115333210000"},"ep08_039":{"who":"RIN","text":"I do not.","mono":false,"off":127.1513,"dur":0.917,"env":"0478942789987665420022100000"},"ep08_040":{"who":"NEMU","text":"You stitched his arm. You tied your wrist to his. You throw pebbles at him.","mono":false,"off":128.4687,"dur":5.163,"env":"00553430475043144644238865533210000000000000000000000670522678888612455326852222003341155431101221000000000000000006841125898740032372244332332211211100000"},"ep08_041":{"who":"RIN","text":"Those are all training.","mono":false,"off":134.0313,"dur":1.301,"env":"0488984488723677621324655554333320000000"},"ep08_042":{"who":"NEMU","text":"The pebbles were not training. I watched. You were smiling.","mono":false,"off":135.7327,"dur":3.755,"env":"01305489237543441068888642004316665332210000000000000036994156643210003430120000000000473655452786666531210000000"},"ep08_043":{"who":"RIN","text":"...He is an idiot who walks ten steps behind everyone so he cannot hurt them. Somebody has to walk back and get him.","mono":false,"off":139.8873,"dur":6.72,"env":"0015777884489610588377877121375468950133021477774331764013104632356666335741466444444434265552114656666511011576400024333210000000000023798877985764466330354358750000655432011344225430203322210000000000"},"ep08_044":{"who":"NEMU","text":"That is what liking someone is. Walking back to get them.","mono":false,"off":147.0073,"dur":3.925,"env":"0377531000009753057302687602166443336655553445421002332000000000000000000000589303399855876420000530047521001210000000"},"ep08_045":{"who":"RIN","text":"Then you like him too.","mono":false,"off":151.3327,"dur":1.301,"env":"0588999977999840216653351565432210000000"},"ep08_046":{"who":"NEMU","text":"I do. He is my first friend in this life. I have only had seven, so it is a short list.","mono":false,"off":153.034,"dur":6.677,"env":"025513587643210000000000001789532365552000046641321300057765434233242022222000000000000000000000000000000000000388771135998787621234530122225530121100000000000001325455154332343323343000033110111201000"},"ep08_047":{"who":"RIN","text":"...You are impossible to argue with.","mono":false,"off":160.1113,"dur":1.899,"env":"015789988877741124664343424651243044554113542343210000000"},"ep08_048":{"who":"NEMU","text":"I know. I am too sleepy to lose.","mono":false,"off":162.41,"dur":2.368,"env":"034876587643200000000000048988653042167443215410232324224553200002431000"},"ep08_049":{"who":"TAKUTO","text":"You are counting again.","mono":false,"off":165.178,"dur":1.301,"env":"0146992024898743454443237653211000000000"},"ep08_050":{"who":"SIEG","text":"You noticed.","mono":false,"off":166.8793,"dur":0.96,"env":"18988877766668654332022210000"},"ep08_051":{"who":"TAKUTO","text":"Your lips move.","mono":false,"off":168.2393,"dur":1.045,"env":"01367447960241466544211100000000"},"ep08_052":{"who":"SIEG","text":"...Mara. She could hit a bird at a hundred paces with a thrown knife. Joss, who snored like a landslide.","mono":false,"off":169.6847,"dur":6.528,"env":"0598665555544420000035735967973765316665665344455427655365430017665432565432004646620012775555655555544332100000000000000003798655554332200000000996333328765555533555404666666666533235443322210000"},"ep08_053":{"who":"SIEG","text":"Little Pell, sixteen, who lied about her age to join. Bram and Bren, the twins. Old Hask, the cook.","mono":false,"off":176.6127,"dur":6.699,"env":"069786411686555533265224203777665530000019887544554645555686214665554330146545686654433221000000000000098766555555665357655555443234630321686666555443210000000017776656347555543400000046102395200000000"},"ep08_054":{"who":"SIEG","text":"Tova. Corin. Dace. Ilse, who wanted to see the sea. And Wen, who I was going to marry in the spring.","mono":false,"off":183.7113,"dur":6.379,"env":"029977656654100228977777665542000068875433323210000000059866532221049877666365313753248754643322776544320000000000006999876655544310000887666675317766665267766555666544665553332007765322110000"},"ep08_055":{"who":"SIEG","text":"Eleven. I count them every night so I remember they were people, not a number on a Guild report.","mono":false,"off":190.49,"dur":5.717,"env":"0699877457665420000000069413796631056630036644777766565302444387555666676777555546654766656510158740054321000000000068777788765555764201477754216876665334751015654210242000"},"ep08_056":{"who":"TAKUTO","text":"And Kurozane was there.","mono":false,"off":196.6073,"dur":1.408,"env":"1452112888983365544443443210454221000000000"},"ep08_057":{"who":"SIEG","text":"Kurozane cut the ropes that would have woken us. Then he walked through our tents while the Rift opened above the pass.","mono":false,"off":198.4153,"dur":6.933,"env":"0139655554554555541116520004655565554310122210004313665643456545410254332222221000000000000002765677765555420011116765544420224755542222100000000366656555555420001000566520354544532544323530036543322123221000"},"ep08_058":{"who":"SIEG","text":"I took his eye. He took Wen. That is the whole story, Takuto. There is no bear and no bishop in it.","mono":false,"off":205.7487,"dur":6.293,"env":"058533931197567655555565100000873396200687666543320000000000005873577631674387656433301766666555421277530178742277544320000000000078887655985565542765555312577775665425654436302544321021000"},"ep08_059":{"who":"TAKUTO","text":"I am sorry, Sieg.","mono":false,"off":212.442,"dur":1.259,"env":"23566563221998765422112433210000000000"},"ep08_060":{"who":"SIEG","text":"Don't be sorry. Rin would say be useful. Go to sleep. That would be useful.","mono":false,"off":214.1007,"dur":4.8,"env":"098642276643228666676666652000000798766555566533322766665576566776533105554420000000788747644333778752000000000000884138754766667753321243221000"},"ep08_061":{"who":"WICK","text":"How did you meet him? Haruki.","mono":false,"off":219.3007,"dur":1.621,"env":"0177463457656664366433111697666520113221110000000"},"ep08_062":{"who":"TAKUTO","text":"Middle school. Three guys from the high school had me against a vending machine.","mono":false,"off":221.322,"dur":4.587,"env":"025588633430027787531000000125764212988765444332103334311345444332002322211000146522444432134431104211155444333232323322221000000000000000"},"ep08_063":{"who":"WICK","text":"And he beat them up?","mono":false,"off":226.3087,"dur":1.045,"env":"05689852997720797777663001220000"},"ep08_064":{"who":"TAKUTO","text":"No. I was beating them up. Badly. He put his hand on my shoulder and said, that is enough, they get it.","mono":false,"off":227.754,"dur":6.08,"env":"003578988741456645431102444545444434433210000000035555531011110000000000000001411393753411455554454344443433355442133333233334433210134443433344444542010002332101455312100000000000000"},"ep08_065":{"who":"TAKUTO","text":"And I stopped. I never stopped for anyone. I stopped for him.","mono":false,"off":234.234,"dur":3.584,"env":"002456667444206988742100000002456665264442086553001144344554333222210024533204754410011232133210000000000000"},"ep08_066":{"who":"WICK","text":"Then he bought you a corn soup.","mono":false,"off":238.218,"dur":1.536,"env":"05678742999951146662021665555333334221000000000"},"ep08_067":{"who":"TAKUTO","text":"...Coffee milk. For the cat. There was a stray cat behind the machine, watching the whole thing.","mono":false,"off":240.154,"dur":5.248,"env":"01139971115445566630000024232011255531100000000000000254433444420136655101134453000332243333333323221233322222221235443113233232113443200013321000000000000000"},"ep08_068":{"who":"WICK","text":"The cat. THE cat.","mono":false,"off":245.802,"dur":1.003,"env":"0431698763385128865532012200000"},"ep08_069":{"who":"TAKUTO","text":"We fed it every night for three years. Then one night he did not come, and I kept feeding it alone.","mono":false,"off":247.2047,"dur":6.144,"env":"01331115985552104541243334333210112210010132222112221100002220000000000000254433565544454433100121133113334442000112444321110000133333201124200110003232232221322233443211000000000000000"},"ep08_070":{"who":"WICK","text":"And now you are almost there. Two days.","mono":false,"off":253.7487,"dur":1.92,"env":"0599999987669898799777764410576554103289477433212332000000"},"ep08_071":{"who":"TAKUTO","text":"What if he does not want to see me?","mono":false,"off":256.0687,"dur":1.856,"env":"00375911143159863235666212455333232213433221000000000000"},"ep08_072":{"who":"WICK","text":"Then you feed him coffee milk until he does. It worked on the cat.","mono":false,"off":258.3247,"dur":3.264,"env":"04667511456467552224896114656655530133422544542466542123332000004532477510245444301355331000000000"},"ep08_073":{"who":"NEMU","text":"There is a letter on the gate. Nailed with a tooth.","mono":false,"off":261.9887,"dur":3.435,"env":"01245665454346786243210000049765404442110013000000000000000000005799998765442220062140054128420010000000"},"ep08_074":{"who":"RIN","text":"To the Laughing Blade. At moonrise, at this gate. Come alone.","mono":false,"off":265.8233,"dur":3.328,"env":"0132988997521167872268777654410000562279999876766665434103444303754320031000114666555554433221000000"},"ep08_075":{"who":"RIN","text":"Or I visit the little cat first. Kurozane.","mono":false,"off":269.5513,"dur":2.624,"env":"0489986478943994486006558574011566201115765431231120000111787875446544333100000"},"ep08_076":{"who":"NEMU","text":"I am the little cat.","mono":false,"off":272.5753,"dur":1.365,"env":"00359868988977637543103224432100041000000"},"ep08_077":{"who":"WICK","text":"He knows about Nemu? How does he know about Nemu?","mono":false,"off":274.3407,"dur":2.56,"env":"04667777454398513565556655433200012674354435665566237621344444332211100000000"},"ep08_078":{"who":"SIEG","text":"Because he has been watching us since the Greatwood.","mono":false,"off":277.3007,"dur":2.923,"env":"0862697543677876554357666666555542033566554554221000000026864310565448766520034332110000"},"ep08_079":{"who":"TAKUTO","text":"We all go.","mono":false,"off":280.6233,"dur":0.939,"env":"03455588752149775321100000000"},"ep08_080":{"who":"SIEG","text":"No.","mono":false,"off":281.962,"dur":0.747,"env":"07987666666654432100000"},"ep08_081":{"who":"TAKUTO","text":"Sieg.","mono":false,"off":283.1087,"dur":0.683,"env":"002229998742264100000"},"ep08_082":{"who":"SIEG","text":"He wants a duel. If he sees five of us, he will not fight. He will run, and he will come back for Nemu on a night I am asleep.","mono":false,"off":284.1913,"dur":8.0,"env":"039887655422366542787664432210000000004727964335765554310065556556446544322000006877767765542011104756532112100000000000000898876656665555444410000004879976652137755543665410014777666666665565202566556666555411000256655555444432454321000000"},"ep08_083":{"who":"SIEG","text":"If I go alone, it ends tonight. One way or the other.","mono":false,"off":292.5913,"dur":3.84,"env":"07548675549666666777666665554100005841036766643123787666543133100000000007987667667666566520026775577666532332210000"},"ep08_084":{"who":"RIN","text":"One way or the other is not good enough.","mono":false,"off":296.8313,"dur":2.24,"env":"02699999898888752277346426750554320025363677651002644454321011100000"},"ep08_085":{"who":"SIEG","text":"It is the only way there is, Rin. I have waited six years for him to stop running.","mono":false,"off":299.4713,"dur":5.184,"env":"067786537520167655556655655555434665556555433321000005987754332100000000000047999655676554565433226412323776555543204664686553235432066653000577544321110000"},"ep08_086":{"who":"NEMU","text":"...I do not want to be the reason you fight.","mono":false,"off":305.0553,"dur":2.325,"env":"0035943978975400004665300001410455044215666554233343321111422100002000"},"ep08_087":{"who":"SIEG","text":"You are not the reason, Nemu. You are just the threat. The reason is eleven names long.","mono":false,"off":307.7807,"dur":5.419,"env":"1998777765410077667766654575554202677777666654541000000008987634586443003741112488642012100000000000888997676566664200586314776766456666666665655442666554322110000"},"ep08_088":{"who":"SIEG","text":"One more lesson. Before moonrise. Pick up the axe.","mono":false,"off":313.5993,"dur":3.243,"env":"19876667665566666564324755442000000079417878887666666655556654200000195257300663256643200333310000"},"ep08_089":{"who":"TAKUTO","text":"Why now?","mono":false,"off":317.242,"dur":0.811,"env":"0259988778887542210000000"},"ep08_090":{"who":"SIEG","text":"Because if tonight goes badly, I want my last lesson to be a good one.","mono":false,"off":318.4527,"dur":4.48,"env":"065259754203631023776555410005655543210554454234544420000000002677665411454555554444321046654322543320000014657655442147643333221100000"},"ep08_091":{"who":"SIEG","text":"Attack me. First move. Always the first move.","mono":false,"off":323.3327,"dur":3.029,"env":"0663479751007766654100048766530298766555431000000005766666566533762006766642067544322100000"},"ep08_092":{"who":"SIEG","text":"Again. And look where my second cut will be, not my first.","mono":false,"off":326.762,"dur":3.669,"env":"188788776666553000389998630006876765675432763057641269520057765458765543100000007976204766762118754322332010000"},"ep08_093":{"who":"TAKUTO","text":"Your second cut comes from the same place as the first.","mono":false,"off":330.8313,"dur":3.051,"env":"01454322894034311158620011444432101333322113444443011433221100023210210004543100011000000000"},"ep08_094":{"who":"SIEG","text":"Every time. Afterimage is honest. That is its weakness. Kurozane knows it. He has known for six years.","mono":false,"off":334.282,"dur":6.805,"env":"0585566532286556555554100000576520157766665544356652125665665433210000000000058746876763121379742001765432220000000000298766656766666665555664465310000000000299876598655555521653321741132177644332222210000"},"ep08_095":{"who":"TAKUTO","text":"Then how do you beat him?","mono":false,"off":341.4873,"dur":1.387,"env":"027555579955434432035543141421110000000000"},"ep08_096":{"who":"SIEG","text":"You make your honest cut lie. You miss on purpose, so the echo lands where he runs.","mono":false,"off":343.274,"dur":5.141,"env":"07998766420028730036665666632010139510167665554454100000000007988765326556630138664105543332100000002298685125510377676666666664335666666567654333222321000"},"ep08_097":{"who":"TAKUTO","text":"Does that work?","mono":false,"off":348.8153,"dur":1.003,"env":"0365423987422477753210000000000"},"ep08_098":{"who":"SIEG","text":"I have never tried it. I have been saving it. For one person.","mono":false,"off":350.218,"dur":3.733,"env":"0689867976644665225348655676564211000000001799974677754324766656766555411100000000898777655651297654332533321000"},"ep08_099":{"who":"SIEG","text":"Takuto. If I lose tonight, do not chase him. Do not open the door in that axe for me.","mono":false,"off":354.3513,"dur":5.525,"env":"0288653011976422876655554100000004844767776756643025766555521000008777542114366565332175332200000000000498865530037763036666543766555555555541003664124311654433210000"},"ep08_100":{"who":"SIEG","text":"Go to Saint Lumen. Find your friend. That is what I want. Promise me.","mono":false,"off":360.2767,"dur":4.523,"env":"0497763266433975315887666555553000000005966666566631117766665554300000000487625976567655766666656543212100000000279767765433156543321000"},"ep08_101":{"who":"TAKUTO","text":"...I promise to go to Saint Lumen.","mono":false,"off":365.1993,"dur":1.92,"env":"0017871011899967543024237873533345431245554321110000000000"},"ep08_102":{"who":"SIEG","text":"That is not the whole promise.","mono":false,"off":367.5193,"dur":2.027,"env":"0798621159769987555541000078632797667751027866666443333221000"},"ep08_103":{"who":"TAKUTO","text":"It is the part I can keep.","mono":false,"off":369.946,"dur":1.536,"env":"04558642371126987523443013433011143200000000000"},"ep08_104":{"who":"SIEG","text":"...Ha. You are getting clever. I hate it.","mono":false,"off":371.882,"dur":2.347,"env":"00249765556666665567576762136876566555520000001789969977633554213210000"},"ep08_105":{"who":"RIN","text":"He said alone. He did not say how far away we have to stay.","mono":false,"off":374.6287,"dur":3.413,"env":"0463439975987899986654310001736727976124368764224775111077666676448666534522343100223341253221100000000"},"ep08_106":{"who":"TAKUTO","text":"The bamboo above the gate. You can see the whole shrine from there.","mono":false,"off":378.442,"dur":3.84,"env":"02326988776316998787522666211242114775210000000000002421565344356266212776543543215666655542113233223221100000000000"},"ep08_107":{"who":"WICK","text":"Are we disobeying Sieg? We are disobeying Sieg. I love it. I hate it. I love it.","mono":false,"off":382.682,"dur":4.395,"env":"057586347443995368766556333336664210146676335443676315756555423333443210000057655799336500266541277652431000045544565103200000000000"},"ep08_108":{"who":"NEMU","text":"If the wolf wins, he comes for me anyway. I would rather be there when he does.","mono":false,"off":387.4767,"dur":5.717,"env":"0421126521477631100148987533211333200000000000004203248665543103566430049855420211000000000000000000000000000000000036853743026666246403445403544322201334420432210002332000"},"ep08_109":{"who":"RIN","text":"Nobody interferes unless Sieg is going to die. Nobody. Not even if he is losing.","mono":false,"off":393.594,"dur":5.056,"env":"03678982287464136722311016666664325555554233332355313633015755543113115544432221000000000268889515654323322100000466641355145542012455231345432223110000"},"ep08_110":{"who":"TAKUTO","text":"How do we know the difference?","mono":false,"off":399.05,"dur":1.536,"env":"00137998486466556676425216741113211023210000000"},"ep08_111":{"who":"RIN","text":"Losing is when he is still laughing. Dying is when he stops.","mono":false,"off":400.986,"dur":3.328,"env":"0369776337775563222776545664223147754455654200042222000000005877666554334212544432221543221001121000"},"ep08_112":{"who":"WICK","text":"He has not laughed in a week.","mono":false,"off":404.714,"dur":1.387,"env":"058975689873368877510266654554310010000000"},"ep08_113":{"who":"RIN","text":"...Then we watch very closely.","mono":false,"off":406.5007,"dur":1.643,"env":"02588998648887402420386676202056653331232210000000"},"ep08_114":{"who":"SIEG","text":"Valentine. If this letter reaches you, I lost a duel I picked myself. Please do not cry. Blame the allergies.","mono":false,"off":408.5433,"dur":7.36,"env":"07865565553268666666552000000000287200874316766466656764313277544776641002676665554204664278665543345520016410027555332475432110000000000000169888651178766554200022865555444310000000018877776766311466556653333432212322000"},"ep08_115":{"who":"SIEG","text":"The boy is good. Better than he knows. Keep Vesper away from him, and keep Gideon making him things.","mono":false,"off":416.3033,"dur":6.016,"env":"0586427555555434543002765543210000000057656644656777665555533322232100000000001296300257544101666655545531165555765444100000376222853100067456555555555531046667544111665332212322000"},"ep08_116":{"who":"SIEG","text":"And tell Tofu I was sorry about calling him a breadbox. He was a very good breadbox.","mono":false,"off":422.7193,"dur":5.632,"env":"0685339755312277665211666651000000004676664322554455555554365310015755555667543144310665443245433220033220000000000000888767765475545554436754320276644314433220003322000"},"ep08_117":{"who":"KUROZANE","text":"You came alone. I almost did not believe it.","mono":false,"off":428.7513,"dur":3.029,"env":"0035411279877875588765433221001445555555533200341134455410004322333321022110000000000000000"},"ep08_118":{"who":"SIEG","text":"You said moonrise. It is moonrise.","mono":false,"off":432.1807,"dur":2.453,"env":"07984229744787665556666556665431000000028888765799866666666554444322321000"},"ep08_119":{"who":"KUROZANE","text":"Six years, Valen. I wear your mark every day. I cannot see your face on my left side.","mono":false,"off":435.034,"dur":5.867,"env":"00112892022137989865221139988644444321001566437899855766667797510102541144311555432110000000013301276678520122244445410006654312233333332234420011114443221110000000000000000000"},"ep08_120":{"who":"SIEG","text":"Then stand on my right. I will try to make it quick.","mono":false,"off":441.3007,"dur":3.115,"env":"0598875431387766667766676556776776666542131000000001799875457766668887741651001198630001100000"},"ep08_121":{"who":"KUROZANE","text":"There. That laugh. I hated that laugh. I came for that laugh.","mono":false,"off":444.8153,"dur":3.904,"env":"0016899874278752146665543200013331035553352114432012443322100000000023200125444310032233211233221100000000000000000000"},"ep08_122":{"who":"KUROZANE","text":"Kurozane, Fang of the Grey. Draw.","mono":false,"off":449.1193,"dur":2.645,"env":"00117999963487665540002865555421241115666543221100000134555433211000000000000000"},"ep08_123":{"who":"SIEG","text":"Sieg Valen. Laughing Blade. Already drawn.","mono":false,"off":452.1647,"dur":2.987,"env":"024397556657655566655554000000379765215677537666666554210000005777765765346876654332210000"},"ep08_124":{"who":"KUROZANE","text":"Fang Draw.","mono":false,"off":455.5513,"dur":1.344,"env":"00009987887788731246877755332110000000000"},"ep08_125":{"who":"SIEG","text":"Fast. Faster than before.","mono":false,"off":457.2953,"dur":2.091,"env":"049665664301000006865543018887764213688776786311587654433210000"},"ep08_126":{"who":"KUROZANE","text":"You are slower, Valen. Six years of counting the dead makes an old man.","mono":false,"off":459.786,"dur":4.843,"env":"00136789952322204688876665542113554432221111000000011571011114565421320001145542013333232100555542112322001132122222002322221111010000000000000000"},"ep08_127":{"who":"SIEG","text":"Afterimage!","mono":false,"off":465.0287,"dur":1.109,"env":"0688763211899988898765555533200000"},"ep08_128":{"who":"KUROZANE","text":"I know your echo, old man! I have dreamed about it!","mono":false,"off":466.538,"dur":3.499,"env":"002566668898845763147400156554214433112443333222211000001233321101123444333131143332111100000000000000000"},"ep08_129":{"who":"KUROZANE","text":"Second Fang!","mono":false,"off":470.4367,"dur":1.323,"env":"0001179930486531002644433221111000000000"},"ep08_130":{"who":"SIEG","text":"Ngh!","mono":false,"off":472.1593,"dur":1.067,"env":"09998999889888889765323222210000"},"ep08_131":{"who":"KUROZANE","text":"Do you know what I was, Valen, before the suit found me? A hound of the Rift. A Calamity's dog, on a chain.","mono":false,"off":473.626,"dur":6.891,"env":"013457879995798798863589852211177764333333312300045413233325530000005444433322221100000000222222566655544311342235664200000000000200235555555654344321001766665432100122221013421433222111110000000000000000000"},"ep08_132":{"who":"KUROZANE","text":"He broke my chain and gave me a name. I have owed him for every breath since. Even this one.","mono":false,"off":480.9167,"dur":5.909,"env":"0023104999200145543102331333332222212210233320022222222222111110000000000024344121256554133221002310234112321003444210011121110000100001221122211023111101111100000000000000000000"},"ep08_133":{"who":"SIEG","text":"So you paid him in my squad.","mono":false,"off":487.226,"dur":2.027,"env":"0369987641169666579866640000168877556753320077666544332110000"},"ep08_134":{"who":"KUROZANE","text":"I paid him in my honour. Your squad was the price of the paper it was written on.","mono":false,"off":489.6527,"dur":5.035,"env":"01677103289896367676666555443124444432111100000001365334410069999877322442103200116776422131131011454100343331123111354100133222221111100000000000000000"},"ep08_135":{"who":"KUROZANE","text":"Third Fang!","mono":false,"off":495.0873,"dur":1.237,"env":"00028888997321000665443221111000000000"},"ep08_136":{"who":"SIEG","text":"Echo!","mono":false,"off":496.7247,"dur":0.768,"env":"068752289877666654210000"},"ep08_137":{"who":"KUROZANE","text":"Ha!","mono":false,"off":497.8927,"dur":0.683,"env":"000137999875543210000"},"ep08_138":{"who":"SIEG","text":"...Mara. Joss. Pell.","mono":false,"off":498.9753,"dur":1.6,"env":"069865555555543333576545643200004976543333210000"},"ep08_139":{"who":"KUROZANE","text":"Are you praying?","mono":false,"off":500.9753,"dur":1.365,"env":"00489974579720111787664333211110000000000"},"ep08_140":{"who":"SIEG","text":"Counting. Bram. Bren. Hask.","mono":false,"off":502.7407,"dur":2.133,"env":"0198666632676666641586666666652000089665565544212876433333000000"},"ep08_141":{"who":"SIEG","text":"Tova. Corin. Dace. Ilse.","mono":false,"off":505.274,"dur":2.197,"env":"029866655654320339766667655554200007766666322210002786443222221000"},"ep08_142":{"who":"KUROZANE","text":"Missed! You MISSED!","mono":false,"off":507.8713,"dur":1.408,"env":"0135789721001345544555431000000110000000000"},"ep08_143":{"who":"SIEG","text":"Wen.","mono":false,"off":509.6793,"dur":0.747,"env":"08997677677765432100000"},"ep08_144":{"who":"KUROZANE","text":"The echo... came from where I ran. You lied. Your blade lied.","mono":false,"off":510.826,"dur":3.904,"env":"0035688820269986400011566532356556666555422444443222110002323555544322210000231013554421133333321111000000000000000000"},"ep08_145":{"who":"SIEG","text":"Once. I saved it for you.","mono":false,"off":515.13,"dur":1.792,"env":"079987665332000479843278777658741101888777754433210000"},"ep08_146":{"who":"SABLE","text":"Oh, how lovely. A song. I do hate to interrupt.","mono":false,"off":517.322,"dur":3.797,"env":"000168995333767544554211233321000124799754454233210000133223333223331012223232222332100001100100000000000000000000"},"ep08_147":{"who":"KUROZANE","text":"Sable. This is MY duel.","mono":false,"off":521.5193,"dur":2.069,"env":"001178994389862236731110133124465443101454333221110000000000000"},"ep08_148":{"who":"SABLE","text":"Everything is yours, Kurozane, until I need it. Pack. Eat the teacher.","mono":false,"off":523.9887,"dur":5.163,"env":"00059833342135543344223354333322454200112354423433223211012433233333344433312210011000000000000012257652000000012320001222122023321211000000000000000000000"},"ep08_149":{"who":"SIEG","text":"Of course.","mono":false,"off":529.5513,"dur":0.917,"env":"0676413696667655433443210000"},"ep08_150":{"who":"TAKUTO","text":"Sieg!","mono":false,"off":530.8687,"dur":0.704,"env":"0122699985237752100000"},"ep08_151":{"who":"SIEG","text":"You followed me. All of you. I told you to stay at the inn!","mono":false,"off":531.9727,"dur":3.328,"env":"0996216966667776458766652000057777765466764443100000000278448877675356442077766530463026865432210000"},"ep08_152":{"who":"RIN","text":"You told us. We did not listen. You are a terrible influence.","mono":false,"off":535.7007,"dur":3.435,"env":"04751328998559843312762772578775225753333444320000003699998874023125667722665246652113544332102221000000"},"ep08_153":{"who":"TAKUTO","text":"Back to back! Rin, the thread!","mono":false,"off":539.5353,"dur":1.707,"env":"0566510157259875400124666555342111146542110000000000"},"ep08_154":{"who":"RIN","text":"Wrist to wrist! Go!","mono":false,"off":541.642,"dur":1.323,"env":"0379723213654577632211101665443322100000"},"ep08_155":{"who":"WICK","text":"Fire head! Only wolves! I am getting really good at only wolves!","mono":false,"off":543.3647,"dur":3.115,"env":"0089865674237751203776667743654442134103565634846554467545311574552554444422443221003321000000"},"ep08_156":{"who":"AKURO","text":"The suit is here, boy. In the trees. I can taste him. Let me...","mono":true,"off":546.8793,"dur":4.224,"env":"0138533344334475421135655765212699998796544224676531222246643443232111100013664213664311113554422211343233346542123433211100000"},"ep08_157":{"who":"TAKUTO","text":"Rin. It wants out.","mono":false,"off":551.5033,"dur":1.259,"env":"02489987533742467751437774211000000000"},"ep08_158":{"who":"RIN","text":"I feel it. Your wrist is hot. Stay with me. Count with Sieg.","mono":false,"off":553.162,"dur":3.264,"env":"05751116899898401367754697230453312367654101222189886661045544320001267752145013334543321000000000"},"ep08_159":{"who":"TAKUTO","text":"...One. Two. Three.","mono":false,"off":556.826,"dur":1.237,"env":"01349865315386542111235553211000000000"},"ep08_160":{"who":"NEMU","text":"Takuto, behind!","mono":false,"off":558.4633,"dur":1.579,"env":"003596021953629875310000377226776532210310000000"},"ep08_161":{"who":"TAKUTO","text":"Four! Break!","mono":false,"off":560.442,"dur":0.981,"env":"001179999853259975320010000000"},"ep08_162":{"who":"KUROZANE","text":"I am not your dog, Sable.","mono":false,"off":561.8233,"dur":2.176,"env":"014577887889995336742129877766542101222145543123221100000000000000"},"ep08_163":{"who":"KUROZANE","text":"Grey Fang. Full Moon.","mono":false,"off":564.3993,"dur":1.941,"env":"00126999861107986544332000003554344444322211111000000000000"},"ep08_164":{"who":"SIEG","text":"He cut his own pack.","mono":false,"off":566.7407,"dur":1.429,"env":"0696326864598652266666666411776543210100000"},"ep08_165":{"who":"SABLE","text":"How disappointing. Well. Dogs bite. I knew that when I bought you.","mono":false,"off":568.57,"dur":4.523,"env":"0002387424698420123544323311221100000124554321100013445442243113332110121000001233354324311222332103442112211111100000000000000000000000"},"ep08_166":{"who":"TAKUTO","text":"Sable!","mono":false,"off":573.4927,"dur":0.747,"env":"00237999737865321000000"},"ep08_167":{"who":"KUROZANE","text":"Valen. This was ours. He made it his. I will not forgive that.","mono":false,"off":574.6393,"dur":4.309,"env":"0011889985665543237422025413346765443322111003344444323100144432111110000001344223444444431000031113310002222110000000000000000000"},"ep08_168":{"who":"KUROZANE","text":"We finish this another night. Without him watching.","mono":false,"off":579.3487,"dur":3.221,"env":"0035410496674320054222444454243334443332100000002420567641123333223444310011121110000000000000000"},"ep08_169":{"who":"SIEG","text":"Kurozane. My eleven. Did you laugh when you killed them?","mono":false,"off":582.97,"dur":3.413,"env":"0249655544555555554200004655555555555543433222000000000375576555544443110356655201156555432123221110000"},"ep08_170":{"who":"KUROZANE","text":"...No. I was told to. I did not. That is the only thing I have that is mine.","mono":false,"off":586.7833,"dur":5.099,"env":"013457789987325663332201135443101213332201233102211333333210000000000355233210032113444343310023322222221123320002222122110222222211111000000000000000000"},"ep08_171":{"who":"RIN","text":"You held on again. With the suit right there.","mono":false,"off":592.282,"dur":2.24,"env":"02696358998299989615866654310165016455549840157665100464332210000000"},"ep08_172":{"who":"TAKUTO","text":"I counted. Like Sieg. One, two, three. It worked.","mono":false,"off":594.922,"dur":3.2,"env":"004521279997427524655214443554321000000000003687651536765311123666443212321224788621000010000000"},"ep08_173":{"who":"RIN","text":"Your wrist was so hot it burned me. Look.","mono":false,"off":598.522,"dur":2.432,"env":"0159964499623115433348775223565523500056555542333322000000024641001000000"},"ep08_174":{"who":"TAKUTO","text":"...Rin, I...","mono":false,"off":601.354,"dur":0.939,"env":"01359998653467753322100000000"},"ep08_175":{"who":"RIN","text":"If you say sorry I will tie your mouth shut. I mean it. I have been practising.","mono":false,"off":602.6927,"dur":4.331,"env":"0402764339976343277777776564674551212456665655665554212333554200000356788877654210110000000056784107764011554100132323322200000000"},"ep08_176":{"who":"TAKUTO","text":"...Thank you, then.","mono":false,"off":607.4233,"dur":1.088,"env":"001159976311356632775422110000000"},"ep08_177":{"who":"RIN","text":"Better.","mono":false,"off":608.9113,"dur":0.576,"env":"199996887653100000"},"ep08_178":{"who":"RIN","text":"I was scared tonight. Not of the wolves. Of the moment the thread would pull, and I would not be strong enough.","mono":false,"off":609.8873,"dur":5.504,"env":"1577574551268776124366665552021046677462127533577765433211232100000000553499999989973004400117986223730000167755433125445564462355530032343245544444433221001000000000"},"ep08_179":{"who":"TAKUTO","text":"Then we both get stronger.","mono":false,"off":615.7913,"dur":1.472,"env":"004555542499741101640342035555432221100000000"},"ep08_180":{"who":"RIN","text":"Faster than he expects. Sieg said that.","mono":false,"off":617.6633,"dur":2.283,"env":"039874214967899887212202764300011000012368742222677322644331010000000"},"ep08_181":{"who":"TAKUTO","text":"Sieg says a lot of things.","mono":false,"off":620.346,"dur":1.557,"env":"00116653112269844644667634100344321110000000000"},"ep08_182":{"who":"RIN","text":"Most of them are even true.","mono":false,"off":622.3033,"dur":1.664,"env":"04799954235218777545640145523654133225543221000000"},"ep08_183":{"who":"RIN","text":"Hold still. That is two cuts across your ribs. He was not playing.","mono":false,"off":624.3673,"dur":3.52,"env":"0038998523330398876542116775476320234751113750134111665322354357555211221015554256552001354433222100000000"},"ep08_184":{"who":"SIEG","text":"Kurozane never plays. That is why he is good at it.","mono":false,"off":628.2873,"dur":3.52,"env":"0139655554455555544444556443354300155554333323210000000001664276545654444554555543200476320145532321011000"},"ep08_185":{"who":"RIN","text":"You stitched Takuto once. Now I stitch you. This is a very stupid family.","mono":false,"off":632.2073,"dur":4.331,"env":"0463322971132022589611385226998657765420222104677888756663230373023235443210000584338548636987763230464027210155545543322200000000"},"ep08_186":{"who":"SIEG","text":"...Family?","mono":false,"off":636.938,"dur":0.917,"env":"0364219977788877665554200000"},"ep08_187":{"who":"RIN","text":"Do not make a thing of it.","mono":false,"off":638.2553,"dur":1.472,"env":"038999999834775036200077666652144320032000000"},"ep08_188":{"who":"SIEG","text":"Ha. Ha ha ha!","mono":false,"off":640.1273,"dur":1.323,"env":"0398776522965676378555764897654444310000"},"ep08_189":{"who":"TAKUTO","text":"You laughed.","mono":false,"off":641.85,"dur":0.811,"env":"0024645977654411001000000"},"ep08_190":{"who":"SIEG","text":"I did. Ow. Ha. It hurts to laugh. Rin, stop stitching while I laugh.","mono":false,"off":643.0607,"dur":4.501,"env":"0588657665431057766554357555542000565599753132028776655543211000000000000898766554431233037654113311742244766665555555655554432110000000"},"ep08_191":{"who":"WICK","text":"He laughed! The Laughing Blade laughed! Somebody write it down!","mono":false,"off":647.962,"dur":2.837,"env":"06679987731003967887611787346888942457665431002345788588576458774521255543221110000000"},"ep08_192":{"who":"NEMU","text":"I will remember it. I am very good at remembering.","mono":false,"off":651.1993,"dur":3.456,"env":"00334126416877779774432210004300000000000000000004599978422298657840014676543231003876676534311111000000"},"ep08_193":{"who":"SIEG","text":"The trick worked. I made the honest blade lie. I am going to be unbearable about this for weeks.","mono":false,"off":655.0553,"dur":5.845,"env":"05734579300078866653000110000000001799876655620256555556531000177666664366665554444420000000000048876676567656634667522467775365556654655544655310057643310476556753100143331000"},"ep08_194":{"who":"TAKUTO","text":"You were already unbearable.","mono":false,"off":661.3007,"dur":1.515,"env":"0035478689858946531356663167666521321100000000"},"ep08_195":{"who":"SIEG","text":"Now I am unbearable with reasons.","mono":false,"off":663.2153,"dur":2.517,"env":"1998766763003677767775100477787627767875476541000007954789777754644323432000"},"ep08_196":{"who":"TAKUTO","text":"Sable was there. He bought Kurozane. He said so.","mono":false,"off":666.1327,"dur":3.072,"env":"001247765267534532126654432211431489610011155555422343221010000023222653112223322100000000000"},"ep08_197":{"who":"SIEG","text":"Then Sable was at Grey Hollow. Not just Kurozane. The man in the suit opened that Rift on my squad himself.","mono":false,"off":669.6047,"dur":6.997,"env":"088875432776755766566764665311117976656764765566543332000000000797520367630001279766765575544433200000000000059997666566666564332786641000057841366655653005876511001002677656634203765555357654332486432111100000"},"ep08_198":{"who":"RIN","text":"The giants. The Hydra. The ogres. Grey Hollow. Nerima. It is all him.","mono":false,"off":677.002,"dur":4.181,"env":"033145976777642124300532257751256530034206886214543223101588663123565545543234556653355555443320033343345433210132210000000000"},"ep08_199":{"who":"TAKUTO","text":"And he is going where we are going.","mono":false,"off":681.5833,"dur":1.856,"env":"00444457443029987544333444323344210467753211000000000000"},"ep08_200":{"who":"NEMU","text":"Are you counting?","mono":false,"off":683.8393,"dur":1.045,"env":"00597671042378987405133221000000"},"ep08_201":{"who":"SIEG","text":"A different list tonight.","mono":false,"off":685.2847,"dur":1.579,"env":"079877862177543677753201100259987665543111100000"},"ep08_202":{"who":"NEMU","text":"Who is on it?","mono":false,"off":687.2633,"dur":0.981,"env":"001198688643666664332100220000"},"ep08_203":{"who":"SIEG","text":"A girl who sleeps all day. A boy whose head is on fire. A girl with her brother's scarf. A boy with an axe that talks back.","mono":false,"off":688.6447,"dur":7.808,"env":"0676796555678643324864213200376655654675443432000000000387576555556668764213866435554665555410065455543332000000000047659765555565177542775536655333300565554321110000000000006864675555555546647641156542003310562003696413300454320000000"},"ep08_204":{"who":"SIEG","text":"Five. All five. Still here.","mono":false,"off":696.8527,"dur":2.048,"env":"00786555675310576664113765555666420000131298777669865433210000"},"ep08_205":{"who":"NEMU","text":"You forgot one.","mono":false,"off":699.3007,"dur":1.045,"env":"00395325512896531200434422100000"},"ep08_206":{"who":"SIEG","text":"Who?","mono":false,"off":700.746,"dur":0.768,"env":"003976555665544432100000"},"ep08_207":{"who":"NEMU","text":"You. You never count yourself. Six.","mono":false,"off":701.914,"dur":2.667,"env":"00499864321676576504302124541014433213222110000000000000000000011217520022111000"},"ep08_208":{"who":"SIEG","text":"...Six.","mono":false,"off":704.9807,"dur":0.811,"env":"0699759988532335755320000"},"ep08_209":{"who":"AKURO","text":"The wolf. Three hundred years ago I knew wolves like him. They die standing up.","mono":true,"off":706.1913,"dur":5.696,"env":"002496333577544211111000012445442235654345311137765542343235555553134444344676631123555455421122245643201112222100000000002443212466565544222332234444432333321222110000000"},"ep08_210":{"who":"TAKUTO","text":"You liked him.","mono":false,"off":712.2873,"dur":0.96,"env":"01355479987200345322110000000"},"ep08_211":{"who":"AKURO","text":"I liked that he refused. Everybody kneels to the suit eventually. That one did not.","mono":true,"off":713.6473,"dur":6.464,"env":"01478777544478886311125853125644674211112256787444222221100000037874367653589886457667877777777754332135434544444566542134314567753443444333221100000000013688862124555432464224445555442210011000"},"ep08_212":{"who":"TAKUTO","text":"Did you kneel? Three hundred years ago?","mono":false,"off":720.5113,"dur":2.176,"env":"025345777788898743100111587765876345222466654442155542110000000000"},"ep08_213":{"who":"AKURO","text":"...Go to sleep, boy. Tomorrow you see the golden city. Look at it carefully. Gold is very good at hiding rot.","mono":true,"off":723.0873,"dur":8.533,"env":"0011103796752244444422236554210003697777786654102346666567778788889623332333345545321267976644324564443333565442211100002467631356565341001112366753112332222110000000000001115888878777632254322211367867655331135666333321222256555433443333334544322100011000"},"ep08_214":{"who":"WICK","text":"Whoa. Whoa. It is so shiny.","mono":false,"off":732.0207,"dur":1.493,"env":"058988754899886646544465433277554321110000000"},"ep08_215":{"who":"RIN","text":"Saint Lumen. The golden capital.","mono":false,"off":733.914,"dur":1.899,"env":"014588513588888755542000631598762365522245410133321100000"},"ep08_216":{"who":"NEMU","text":"It looks like someone dropped the sun and built houses on it.","mono":false,"off":736.2127,"dur":4.16,"env":"02202880232046640221226765543322100000001247754200100444223443311000000000000000000069825974201122556643323233333331110001000"},"ep08_217":{"who":"SIEG","text":"Home of the Gilded Order, the Cathedral, and the Golden Saint himself. Lucien Aurel.","mono":false,"off":740.7727,"dur":5.397,"env":"029765554344446543486555774200566665465544100001632884117775456655400000004887742865554656543237655323765433256653221111000000000000079975444766410266544332210000"},"ep08_218":{"who":"TAKUTO","text":"Haruki is down there.","mono":false,"off":746.57,"dur":1.493,"env":"001799788612134566441166655554332211000000000"},"ep08_219":{"who":"SIEG","text":"If Wick heard right.","mono":false,"off":748.4633,"dur":1.451,"env":"07962688776410011249766665566665554313210000"},"ep08_220":{"who":"WICK","text":"I always hear right. I just do not always hear the important parts.","mono":false,"off":750.314,"dur":3.541,"env":"04742799958997432168875588654310000002774675226788851178875777443116676445656412176424302165431003321000000"},"ep08_221":{"who":"TAKUTO","text":"...Two years. I am coming, Haruki.","mono":false,"off":754.2553,"dur":2.133,"env":"0455753379988553431356554302288564443146855554101132110000000000"},"ep08_222":{"who":"HUNTER","text":"Halt. State your names and your business in the holy city.","mono":false,"off":756.7887,"dur":3.691,"env":"000379986100011038742013434443333332210222222211035421022220000012222101332222100002321111100000000000000000000"},"ep08_223":{"who":"SIEG","text":"Sieg Valen, rank A, of the Ashford Guild. With four Hunters. The Order sent for us.","mono":false,"off":760.8793,"dur":5.44,"env":"02398666867755556665555666666662014676631365567302566542028643218766654442000000000059731004866655338665227754433200000000000693267766765332776421000654432232221000"},"ep08_224":{"who":"HUNTER","text":"Valen. And the white-haired one is the Skyfallen?","mono":false,"off":766.7193,"dur":3.349,"env":"00168999767655421355543358986300135775222333333212210012122101455441000232222111100000000000000000000"},"ep08_225":{"who":"HUNTER","text":"The Saint expects you. All of you. A carriage is waiting.","mono":false,"off":770.4687,"dur":3.605,"env":"0043226987774111007981001124544213677565213344332210012001137776654211232111235444312221100000000000000000000"},"ep08_226":{"who":"WICK","text":"A carriage. A golden carriage.","mono":false,"off":774.474,"dur":1.579,"env":"020129988887333763278774476631267544321122100000"},"ep08_227":{"who":"TAKUTO","text":"Haruki got into a golden carriage. Two years ago. The guild clerk said he waved.","mono":false,"off":776.4527,"dur":5.419,"env":"0015998657851011244311456534432133421114665531333310344432111012200000033454324555433321132221110000000003321169976210021476420233332233222444543110000000000000000"},"ep08_228":{"who":"NEMU","text":"You are not going to wave, are you?","mono":false,"off":782.2713,"dur":2.027,"env":"0011797798651003677764623227653210000011000005976411221000000"},"ep08_229":{"who":"TAKUTO","text":"No.","mono":false,"off":784.698,"dur":0.619,"env":"0145899876432000000"},"ep08_230":{"who":"AKURO","text":"Gold, boy. Everything smells of gold here. And underneath it, something I have smelled before.","mono":true,"off":785.7167,"dur":6.869,"env":"001268864667765312148987998876731015875345420367887533433366877666533234321113774575644311123553321100000000014663476566766664546420135431012334677631135765324554443234432465554433211123211125553332211000000"},"ep08_231":{"who":"TAKUTO","text":"Rin. It is talking.","mono":false,"off":792.986,"dur":1.344,"env":"01367766531165553302148962012211000000000"},"ep08_232":{"who":"RIN","text":"What does it say?","mono":false,"off":794.73,"dur":0.981,"env":"059249559502326865543221000000"},"ep08_233":{"who":"TAKUTO","text":"That this city is hiding something.","mono":false,"off":796.1113,"dur":1.877,"env":"025400596322178645454221136655344421145431002100000000000"},"ep08_234":{"who":"RIN","text":"...Every city is. Let's go find out what.","mono":false,"off":798.3887,"dur":2.325,"env":"0599337753343995766666553221036750230289511166665455531234321001000000"},"ep08_235":{"who":"LUCIEN","text":"A boy with white hair and a red jacket is coming down the mountain road. He says he is your friend.","mono":false,"off":801.114,"dur":5.803,"env":"0774219877787655345311358665401114665644321000037796546976221234875530134102334022575556626755555556655432254544676665322211000000000000005544597443566633364111168654322110000"},"ep08_236":{"who":"HARUKI","text":"...Takuto?","mono":false,"off":807.3167,"dur":1.109,"env":"0463498875126876327766544443200000"},"ep08_237":{"who":"LUCIEN","text":"You told me nobody would come looking for you.","mono":false,"off":808.826,"dur":2.453,"env":"00594063997772266555667988733866344325410327744557511244411254235643210000"},"ep08_238":{"who":"HARUKI","text":"I told you nobody should. He never listens. He never, ever listens.","mono":false,"off":811.6793,"dur":3.52,"env":"0899523886458887777537746543327776422117777784586557653244322331000000888888368525864765567532332212321000"},"ep08_239":{"who":"TAKUTO","text":"Next time: Saint Lumen, the golden capital.","mono":false,"off":815.5993,"dur":2.667,"env":"02589316403999975432101244974224888676655425313888632554311566301323211000000000"},"ep08_240":{"who":"TAKUTO","text":"The Golden Saint invites me to join the Gilded Order.","mono":false,"off":818.666,"dur":3.221,"env":"0310279976125442332443322100000034431277653022033211121223444333332221002443312322112332111100000"},"ep08_241":{"who":"TAKUTO","text":"And Haruki is standing at his side. He doesn't want to be rescued.","mono":false,"off":822.2873,"dur":4.16,"env":"01344226998766751010143332233332044445543433332332322255553211100000000000000426993452234553022133324553330002110000000000000"},"ep08_242":{"who":"TAKUTO","text":"Episode nine. Saint Lumen.","mono":false,"off":826.8473,"dur":1.877,"env":"056104333698732455665432210000122553212344332110000000000"}}};
